const cfg = $input.first().json;
let base = String(cfg.siteBaseUrl || '');
while (base.endsWith('/')) base = base.slice(0, -1);
if (!base.startsWith('http://') && !base.startsWith('https://')) throw new Error('Config: siteBaseUrl must start with http:// or https://');
const saved = $getWorkflowStaticData('global');
const cursor = Number.isInteger(saved.cursor) && saved.cursor >= 0 ? saved.cursor : 0;
const api = base + '/api/automation/social/v1';
return [{ json: { ...cfg, cursor, eventsUrl: api + '/events', runsUrl: api + '/runs' } }];

const cfg = $('Read cursor').first().json;
const res = $input.first().json;
const hour = $now.setZone('Europe/Bucharest').toFormat('yyyy-MM-dd-HH');
const out = { from: cfg.alertFrom, to: cfg.alertTo, cursor: cfg.cursor, nextCursor: cfg.cursor, runsUrl: cfg.runsUrl, send: false, failed: false, alertCount: 0 };
const okStatus = res.statusCode >= 200 && res.statusCode < 300;
if (res.error !== undefined || !okStatus || !res.body || !Array.isArray(res.body.events)) {
  const why = res.error !== undefined ? String(res.error.message || res.error) : 'HTTP ' + res.statusCode + ' ' + JSON.stringify(res.body === undefined ? null : res.body);
  return [{ json: { ...out, failed: true, runEventId: 'events-error-' + hour, runStatus: 'error', runDetails: { stage: 'fetch', message: why.slice(0, 300), after: cfg.cursor } } }];
}
const events = res.body.events;
const WATCH = ['delivery_failed', 'delivery_stale', 'account_reconnect_required', 'manual_due', 'drafts_ready', 'generation_failed', 'foreign_post', 'worker_silent'];
const LABELS = {
  delivery_failed: 'Publicare esuata',
  delivery_stale: 'Publicare expirata',
  account_reconnect_required: 'Cont de reconectat',
  manual_due: 'De publicat manual',
  drafts_ready: 'Ciorne noi',
  generation_failed: 'Generare esuata',
  foreign_post: 'Postare facuta direct in Postiz',
  worker_silent: 'Workerul nu mai raspunde',
};
const maxAgeMs = (Number(cfg.maxAgeHours) > 0 ? Number(cfg.maxAgeHours) : 48) * 3600000;
const now = Date.now();
const short = (v, n) => String(v === undefined || v === null ? '' : v).slice(0, n);
const detail = (e) => {
  const p = e.payload || {};
  if (e.type === 'delivery_failed' || e.type === 'delivery_stale' || e.type === 'manual_due') {
    return [p.platform, p.account, p.error_code, p.error_message].filter(Boolean).map((x) => short(x, 80)).join(' | ');
  }
  if (e.type === 'account_reconnect_required') return short(p.reason || 'reconectare necesara', 80);
  if (e.type === 'drafts_ready') return short(p.created, 6) + ' ciorne create' + (p.skipped ? ', ' + short(p.skipped, 6) + ' sarite' : '');
  if (e.type === 'generation_failed') return [p.error_code, p.error_message].filter(Boolean).map((x) => short(x, 120)).join(': ');
  if (e.type === 'foreign_post') return 'id Postiz ' + short(p.postiz_post_id, 60);
  if (e.type === 'worker_silent') return 'ultimul semn de viata: ' + short(p.last_seen_at, 40);
  return '';
};
const relevant = events.filter((e) => WATCH.includes(e.type) && !(now - Date.parse(e.created_at) > maxAgeMs));
let nextCursor = Number.isInteger(res.body.next_after) ? res.body.next_after : cfg.cursor;
if (events.length > 0) nextCursor = Math.max(nextCursor, events[events.length - 1].id);
nextCursor = Math.max(nextCursor, cfg.cursor);
const NL = String.fromCharCode(10);
const stamp = new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Bucharest', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
const when = (iso) => {
  const p = {};
  for (const x of stamp.formatToParts(new Date(iso))) p[x.type] = x.value;
  return p.day + '.' + p.month + ' ' + p.hour + ':' + p.minute;
};
const lines = relevant.slice(0, 40).map((e) => {
  const d = detail(e);
  return '- ' + when(e.created_at) + ' ' + LABELS[e.type] + (d ? ': ' + d : '');
});
const extra = relevant.length - lines.length;
if (extra > 0) lines.push('... si inca ' + extra + ' evenimente, vezi in aplicatie');
const n = relevant.length;
const subject = n === 1 ? 'Agent Social: ' + LABELS[relevant[0].type] : 'Agent Social: ' + n + ' alerte noi';
const text = (n === 1 ? 'Un eveniment nou in Agent Social:' : n + ' evenimente noi in Agent Social:') + NL + NL + lines.join(NL) + NL + NL + 'Deschide panoul: ' + String(cfg.adminUrl || '') + NL + NL + 'Mesaj automat din n8n.';
return [{
  json: {
    ...out,
    send: n > 0,
    subject,
    text,
    nextCursor,
    alertCount: n,
    runEventId: events.length > 0 ? 'events-' + nextCursor : 'idle-' + hour,
    runStatus: events.length > 0 ? 'ok' : 'skipped',
    runDetails: { from_id: cfg.cursor, to_id: nextCursor, events: events.length, alerts: n, emailed: n > 0 },
  },
}];

const d = $('Build digest').first().json;
const saved = $getWorkflowStaticData('global');
const current = Number.isInteger(saved.cursor) ? saved.cursor : 0;
if (!d.failed && Number.isInteger(d.nextCursor) && d.nextCursor > current) saved.cursor = d.nextCursor;
return [{ json: { url: d.runsUrl, body: { workflow: 'events-to-email', event_id: d.runEventId, status: d.runStatus, details: d.runDetails } } }];

const d = $('Build digest').first().json;
const err = $input.first().json;
const message = String((err.error && err.error.message) || err.error || 'send failed').slice(0, 300);
return [{ json: { url: d.runsUrl, body: { workflow: 'events-to-email', event_id: 'events-mail-error-' + d.nextCursor, status: 'error', details: { stage: 'email', message, from_id: d.cursor, to_id: d.nextCursor, alerts: d.alertCount } } } }];
